give.example:
const { Quest } = kcds.characters;

const delivery = Quest.give('deliver_grain', 'Grain for the mill', {
  player,
  description: 'The miller in Troskowitz needs three sacks of grain.',
  objectives: [
    { text: 'Collect the grain', position: new kcds.math.Vector3(512, 830, 31) },
    { text: 'Bring it to the miller' },
  ],
  track: true,
});

delivery.setObjective(0, { text: 'Collect the grain', progress: 'done' });
delivery.setProgress('done');

give.exampleCs:
var delivery = Quest.Give("deliver_grain", "Grain for the mill", new { player = player, description = "The miller in Troskowitz needs three sacks of grain.", objectives = new object[] { new { text = "Collect the grain", position = new Vector3(512, 830, 31) }, new { text = "Bring it to the miller" } }, track = true });

delivery.SetObjective(0, new { text = "Collect the grain", progress = "done" });
delivery.SetProgress("done");

find.example:
const quest = kcds.characters.Quest.find('deliver_grain', undefined, player);
if (quest) {
  quest.setProgress('done');
}

find.exampleCs:
var quest = Quest.Find("deliver_grain", null, player);
if (quest != null)
{
    quest.SetProgress("done");
}

setObjectives.example:
quest.setObjectives([
  { text: 'Collect the grain', progress: 'done' },
  { text: 'Bring it to the miller', position: new kcds.math.Vector3(512, 830, 31) },
]);
